llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Psilocybin, a tryptamine with a dimethylaminoethyl side chain, had an absolute oral bioavailability of 52.7% in humans, supporting that small aminoethyl indole/oxindole analogues can exceed the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ziprasidone, a lipophilic heterocyclic amine, had an absolute oral bioavailability of 59% after a 20-mg oral dose in the fed state in humans, supporting high oral bioavailability for a lipophilic amine drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Etodolac, a lipophilic heterocyclic drug, had an absolute oral bioavailability of 80% in humans, supporting high oral bioavailability for a moderately lipophilic heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DMT, a tryptamine with a dimethylaminoethyl side chain, had an estimated absolute oral bioavailability of only about 10-15% in volunteers due to extensive first-pass metabolism; this is contradictory evidence, but its MAO-labile tryptamine structure is not shared by the oxindole query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is ropinirole, a lipophilic tertiary-amine oxindole. Most transferable experimental evidence shows moderate-to-high oral bioavailability (psilocybin ~53%, ziprasidone ~60%, etodolac ~80%), supporting F >= 20%. The only low-F analogue, DMT (~10-15%), is a MAO-labile tryptamine and does not reflect ropinirole's oxindole metabolic profile, so it does not outweigh the supportive evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for ropinirole is present in the provided evidence set.",
    "Morgan similarities are low (0.23-0.26), limiting structural transferability.",
    "No evidence directly addresses ropinirole-specific first-pass metabolism (e.g., CYP1A2) or formulation effects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

